import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const hundredSlashCard='a2-p10-r1c3';
export const hundredSlashScenarios=['hundred-slash-ordinary','hundred-slash-owner-ordinary','hundred-slash-low','hundred-slash-owner-low','hundred-slash-dedicated','hundred-slash-pair','hundred-slash-all','hundred-slash-near','hundred-slash-same-faction','hundred-slash-water','hundred-slash-metal','hundred-slash-fort','hundred-slash-maai-one','hundred-slash-maai-three','hundred-slash-parry','hundred-slash-evade','hundred-slash-fate-before','hundred-slash-fate-after','hundred-slash-suppressed','hundred-slash-silenced','hundred-slash-stopped','hundred-slash-wrong-owner','hundred-slash-decline','hundred-slash-noncounter','hundred-slash-unprepared-ordinary','hundred-slash-unprepared-dedicated','hundred-slash-chant-ordinary','hundred-slash-chant-dedicated','hundred-slash-mental-lester','hundred-slash-mental-dia','hundred-slash-mental-gad'] as const;
export type HundredSlashScenario=typeof hundredSlashScenarios[number];
export function isHundredSlashScenario(name:string):name is HundredSlashScenario{return (hundredSlashScenarios as readonly string[]).includes(name);}
export function hundredSlashMode(name:HundredSlashScenario){const suffix=name.replace('hundred-slash-',''),dedicated=!['ordinary','owner-ordinary','low','owner-low','decline','unprepared-ordinary','chant-ordinary','fate-before','fate-after'].includes(suffix),mental=suffix.startsWith('mental-'),owner=dedicated&&suffix!=='wrong-owner'||['owner-ordinary','owner-low'].includes(suffix),targets=['all'].includes(suffix)?[1,2,3]:['pair','maai-one','maai-three','parry','evade','suppressed','silenced'].includes(suffix)||mental?[1,2]:[1],follower=suffix==='water'?'a2-p23-r1c1':suffix==='metal'?'a2-p22-r1c1':suffix==='fort'?'a2-p19-r1c3':null,ability=suffix==='mental-lester'?'c2-p03-r2c1-ab01':suffix==='mental-dia'?'c2-p06-r1c2-ab01':suffix==='mental-gad'?'c2-p06-r1c1-ab01':null;return {suffix,dedicated,owner,mental,targets,follower,ability};}
/** Only initial deal/training is arranged. Followers, OPEN, statuses and preparation use accepted commands. */
export function makeHundredSlashPhysical(name:HundredSlashScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;prepared?:boolean;warrior?:number;spirit?:number;targetSpirit?:number}={}){
 const m=hundredSlashMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'侍大将のシン':'黒騎士ガーウィン',m.suffix==='mental-lester'?'吟遊詩人のレスター':m.suffix==='mental-dia'?'魔聖母ディア':m.suffix==='mental-gad'?'不死王ガドューラ':'黒妖精のアーネス',m.suffix==='same-faction'?'大神官ジル':'魔導王ガイナス','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??(m.mental?3:6):p.id===b?options.targetSpirit??11:p.id===c?12:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(['low','owner-low','fate-after'].includes(m.suffix)?6:m.dedicated?0:7))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,hundredSlashCard),takeCard(s,d,'a2-p02-r2c3')];if(m.follower)keep.push(takeCard(s,b,m.follower));if(m.suffix==='near')keep.push(takeCard(s,a,'a2-p24-r1c3'));if(m.suffix.startsWith('maai'))keep.push(takeCard(s,b,'a2-p06-r1c3'),takeCard(s,b,'a2-p06-r2c1'),takeCard(s,b,'a2-p06-r2c2'));if(m.suffix==='evade')keep.push(takeCard(s,b,'a2-p05-r3c1'));if(m.suffix==='parry')keep.push(takeCard(s,b,'a2-p12-r1c3'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`HUNDRED_SLASH_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('HUNDRED_SLASH_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('HUNDRED_SLASH_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('HUNDRED_SLASH_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(m.follower&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:m.follower});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 act(a,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(a,{type:'CHOOSE_DRAW',draw:false});if(['stopped','decline'].includes(m.suffix)||m.suffix.startsWith('unprepared')||m.suffix.startsWith('chant-')||options.prepared===false)return s;
 act(a,{type:'CHANT',cardInstanceId:hundredSlashCard,dedicated:m.suffix==='wrong-owner'?false:m.dedicated});for(let n=0;n<250;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'},prior?6:1);else if(s.phase==='action'){if(id===a)break;if(incoming&&id===b){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let k=0;k<300;k++){if(s.windows?.at(-1)?.kind==='normal-defense')return s;const next=s.windows!.at(-1)!;act(next.participants[next.cursor]!,{type:'PASS'});}throw Error('HUNDRED_SLASH_INCOMING_LIMIT');}act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.slice(gameStats(s,id).handLimit)});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('HUNDRED_SLASH_TURN');}
 if(m.suffix==='near'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
